        if(previousRevision)await client.query(`INSERT INTO tool_research_claim_evidence(claim_id,revision,evidence_id,stance,evidence_authority_tier) SELECT claim_id,$2,evidence_id,stance,evidence_authority_tier FROM tool_research_claim_evidence WHERE claim_id=$1 AND revision=$3 ON CONFLICT(claim_id,revision,evidence_id) DO NOTHING`,[claim.id,revision,previousRevision]);
