        if(finding.kind==='contradiction'){const related=(await client.query(`SELECT id,current_revision,status FROM tool_research_claims WHERE topic_id=$1 AND finding_id=$2 FOR UPDATE`,[job.topic_id,finding.contradictsFindingId])).rows[0];if(!related||related.id===claim.id)throw new ResearchTopicError('RESEARCHER_CONTRADICTION_TARGET_NOT_FOUND',409,'矛盾结论指向的既有 findingId 不存在。');const dedupeKey=digest({type:'contradiction',claimId:claim.id,revision,relatedClaimId:related.id});await client.query(`INSERT INTO tool_research_claim_review_signals(id,topic_id,claim_id,revision,signal_type,severity,reason,related_claim_id,dedupe_key) VALUES($1,$2,$3,$4,'contradiction',$5,$6,$7,$8) ON CONFLICT(topic_id,dedupe_key) DO NOTHING`,[crypto.randomUUID(),job.topic_id,claim.id,revision,finding.importance,`Researcher 明示该候选与 findingId ${finding.contradictsFindingId} 存在矛盾；平台未自动撤销被指向结论。`,related.id,dedupeKey]);}
