    if(!exact(finding,['findingId','kind','title','summary','importance','confidence','evidence'],['fact','metric','contradictsFindingId'])||!['findingId','kind','title','summary','importance'].every(field=>typeof finding[field]==='string')||!findingId||findingIds.has(findingId)||!findingKinds.has(finding.kind)||!clean(finding.title,240)||!clean(finding.summary,4000)||!importanceLevels.has(finding.importance)||!Number.isFinite(finding.confidence)||finding.confidence<0||finding.confidence>1||!Array.isArray(finding.evidence)||finding.evidence.length<1||finding.evidence.length>20)fail('RESEARCHER_FINDING_INVALID',422,'Researcher 结论格式无效或 findingId 重复。');
    const contradictsFindingId=finding.kind==='contradiction'?clean(finding.contradictsFindingId,120):null;if(finding.kind==='contradiction'&&(!contradictsFindingId||contradictsFindingId===findingId)||finding.kind!=='contradiction'&&finding.contradictsFindingId!==undefined)fail('RESEARCHER_FINDING_INVALID',422,'矛盾结论必须指向另一条既有 findingId。');
