  const failJob=async(jobId,body)=>{const result=await repository.failJob(id(jobId,'Researcher 任务'),id(body?.attemptId,'执行尝试'),{code:clean(body?.code,120)||'RESEARCHER_FAILED',message:clean(body?.message,500)||'Researcher 未完成任务。',retryable:Boolean(body?.retryable)});if(!result)fail('RESEARCHER_LEASE_LOST',409,'Researcher 任务租约不存在或已过期。');return result;};
  const requireLocalLease=async(node,jobId,body)=>{const safeJobId=id(jobId,'Researcher 任务'),attemptId=id(body?.attemptId,'执行尝试');if(!await repository.assertLocalLease(node.userId,node.id,safeJobId,attemptId))fail('RESEARCHER_LEASE_LOST',409,'本地节点没有该任务的有效租约。');return{safeJobId,attemptId};};
  const requireLocalAttempt=async(node,jobId,body)=>{const safeJobId=id(jobId,'Researcher 任务'),attemptId=id(body?.attemptId,'执行尝试');if(!await repository.assertLocalAttempt(node.userId,node.id,safeJobId,attemptId))fail('RESEARCHER_LEASE_LOST',409,'本地节点不是该任务尝试的所有者。');return{safeJobId,attemptId};};
