      const pack=await repository.evidencePackForRun(run.user_id,run.topic_id,runId,100);if(!pack.length)return{status:'no_evidence'};
      const gap=await repository.createAutomaticGap(run.user_id,run.topic_id,{id:ids(),question:clean(`${run.title}：从本轮新增新闻证据中提取可比较的关键事实，并判断是否需要提出或修订分析结论。`,500),hash:digest({kind:'automatic-news-analysis',runId}),reason:clean(`系统在新闻观察运行 ${runId} 中归档了 ${pack.length} 条最小证据，等待结构化分析。`,1000)});
      if(!gap)return{status:'run_unavailable'};
